@testset "SCFT regression (pre-refactor fingerprints)" begin
    for (name, f) in SCFT_REGRESSION_CASES
        @testset "$name" begin
            got, ref = scft_fingerprint(f()), SCFT_GOLDEN[name]
            @test length(got) == length(ref)
            for α in 1:(length(ref) ÷ 5)
                r = (5α - 4):(5α)
                # mean: tight; deviations: compared as a block so near-zero entries
                # are judged relative to the perturbation size, not to themselves.
                @test isapprox(got[r[1]], ref[r[1]]; rtol=1e-10)
                @test isapprox(got[r[2:end]], ref[r[2:end]]; rtol=1e-6)
            end
        end
    end
end
